@keyframes fade-in-base {
  0% {
    opacity: 0;
    transform: translateY(60px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}
@keyframes fade-in-scale {
  0% {
    opacity: 0;
    transform: scale(1.1);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}
@keyframes fade-out-base {
  0% {
    opacity: 1;
    transform: translateY(0);
  }
  to {
    opacity: 0;
    transform: translateY(-60px);
  }
}
@keyframes opacity-in-base {
  0% {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}
@keyframes opacity-out-base {
  0% {
    opacity: 1;
  }
  to {
    opacity: 0;
  }
}
@keyframes scale-in-bottom {
  0% {
    opacity: 0;
    transform: scaleY(0);
    transform-origin: bottom;
  }
  to {
    opacity: 1;
    transform: scaleY(1);
    transform-origin: bottom;
  }
}
@keyframes scale-in-left {
  0% {
    opacity: 0;
    transform: scaleX(0);
    transform-origin: left;
  }
  to {
    opacity: 1;
    transform: scaleX(1);
    transform-origin: left;
  }
}
@keyframes scale-in-center {
  0% {
    opacity: 0;
    transform: scale(0.8);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}
@keyframes scale-down-center {
  0% {
    opacity: 0;
    transform: scale(2);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}
@keyframes slide-in-left {
  0% {
    opacity: 0;
    transform: translate(-60px);
  }
  to {
    opacity: 1;
    transform: translate(0);
  }
}
@keyframes slide-in-right {
  0% {
    opacity: 0;
    transform: translate(60px);
  }
  to {
    opacity: 1;
    transform: translate(0);
  }
}
@keyframes slide-in-bottom {
  0% {
    opacity: 0;
    transform: translateY(100px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}
@keyframes hover-base {
  0% {
    transform: scale(1);
    opacity: 1;
  }
  to {
    transform: scale(1.05);
    opacity: 0.9;
  }
}
@keyframes pressed-base {
  0% {
    transform: scale(1);
  }
  to {
    transform: scale(0.95);
  }
}
@keyframes selected-base {
  0% {
    transform: scale(1);
    opacity: 1;
  }
  to {
    transform: scale(1.02);
    opacity: 0.95;
    box-shadow: 0 4px 12px #00000026;
  }
}
