/* ===== shadowRoot.adoptedStyleSheets ===== */
:host {
  --ump-aspect-ratio: unset;
  --ump-height: unset;
  container: universalmediaplayer / size;
  display: inline-block;
  position: relative;
  width: 100%;
  height: var(--ump-height);
  aspect-ratio: var(--ump-aspect-ratio);
  background-color: var(--color-black);
  font-family: var(--font-family-default);
  font-size: var(--font-size-base-300);
  word-break: normal;
  min-width: 320px;
  min-height: 256px;
}
video {
  object-fit: contain;
}
.fill-parent {
  position: absolute;
  inset: 0px;
  width: 100%;
  height: 100%;
}
ump-controls {
  z-index: 10;
}
ump-modals {
  z-index: 20;
}
ump-loading-spinner {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  z-index: 15;
}

